export default class ArgesonPlayer {
  constructor() {
    this.plugId = null
    this.islocal = 0
    this.errorCount = 0
    this.initWinNum = 1
    this.currentWinCameraid = null
    this.currentWinNo = 0
    this.currentDeviceCode = null
    this.currentMediaAccount = null
    this.currentName = ''
    this.noVersionCount = 0
    this.oWebControl = null
    this.container = null
    this.vRecordInfo = []
    this.storageType = 1
    this.isClosed = false
  }

  initPlugin(container, callbackFunc, reloadCount = 0) {
    callbackFunc = callbackFunc || {
      getCurrentWinId: null,
      reloadPlugin: null,
      reloadVideo: null,
      videoPlayBack: null,
      downloadVideo: null,
      downloadPlugin: null,
    }
    return new Promise((resolve, reject) => {
      try {
        this.container = container
        this.oWebControl = new ArgesWebControlPlug(
          {
            plugnContainer: container,
            offset: '0 0',
            connSuccess: (vid) => {
              this.plugId = vid
              resolve(this)
              setTimeout(this.checkClose.bind(this), 100)
            },
            connError: (version) => {
              console.log('连接失败-----------------')
              this.oWebControl = null
              ArgesWebControlPlug.JS_WakeUp(`ArgesWebControll${version}://`)
              if (reloadCount < 3) {
                setTimeout(() => {
                  if (!version && callbackFunc.downloadPlugin)
                    callbackFunc.downloadPlugin()
                })
              } else {
                console.log('插件加载失败，请检查插件是否安装！')
                this.isClosed = true
              }
            },
            connClose: () => {
              console.log('插件关闭-------------------')
              this.destroy()
              this.oWebControl = null
            },
            winSelected: (cameraid, winNo) => {
              if (Number.isInteger(winNo)) {
                this.checkClose()
                this.getPluginVersion()
                this.currentWinCameraid = cameraid
                console.log(`当前选中窗口号[${winNo}]`)
                if (callbackFunc.getCurrentWinId)
                  callbackFunc.getCurrentWinId(cameraid, winNo)
              }
            },
            ptzCommand: (operType, operContent, gacode) => {
              console.log(operType, operContent, gacode)
            },
            showVersion: (version) => {
              if (!version) this.noVersionCount++
              if (version) this.noVersionCount = 0
              if (!version && callbackFunc.reloadPlugin && this.noVersionCount === 2) {
                console.log('-----------------------noVersion>3-------------------------')
                callbackFunc.reloadPlugin('crash')
              }
            },
            getSplitNum: (splitNum) => {},
            videoresult: (resultcode, gacode, winNo, tagId) => {
              console.log('播放结果回调执行, gacode, tagId', gacode, tagId)
              if (resultcode === 0) console.log(`窗口${winNo}播放成功，通道编码${gacode}`)
              if (resultcode === 1) console.log(`窗口${winNo}关闭，通道编码${gacode}`)
              if (resultcode > 1000) {
                console.log('播放失败')
                if (callbackFunc.reloadVideo) callbackFunc.reloadVideo(winNo)
              }
            },
            fullScreen: (mode, status) => {
              console.log('mode', mode)
              console.log('status', status)
            },
            playbackresult: (resultcode, gacode, winNo) => {
              console.log('resultcode', resultcode)
              console.log('gacode', gacode)
              console.log('winNo', winNo)
            },
            switchStream: (gacode, winNo, streamType) => {
              console.log(`当前码流类型(1-主码流,2-辅码流):${streamType}`)
              this.pullAgainSwich(gacode, winNo, streamType)
            },
            switchLayout: (splitNum) => {
              if (this.isClosed) this.destroy()
            },
            playbackDownload: (gacode, rowId, begintime, endtime) => {
              if (callbackFunc.downloadVideo)
                callbackFunc.downloadVideo(gacode, rowId, begintime, endtime)
            },
            winClicked: (gacode, x, y, winNo) => {},
            winNum: this.initWinNum,
            captionBar: true,
            cache: false,
            menuLimit: {
              LPause: true,
              L3Dlocation: false,
              LTalk: false,
              LAudio: false,
              LCapture: true,
              LLocalRecord: false,
            },
          },
          null,
        )
      } catch (e) {
        reject(false)
      }
    })
  }

  playVideo(codingDeviceId, mediaAccount, name, winNo) {
    this.setCurrentDevice(codingDeviceId, mediaAccount, name)
    const data = {
      streamType: currentStreamType,
      protocolType: 6,
      netType: this.islocal,
    }
    const url = `${southAddr}/devices/${this.currentDeviceCode}/channels/${this.currentMediaAccount}/getVideoRealtimeUrl`
    post(url, data, {
      headers: {
        'X-ServerCode': 'getVideoRealtimeUrl',
        'X-PlugId': this.plugId,
      },
    }).then(({ data: result }) => {
      const url = result.data.streamUrl
      if (winNo !== undefined)
        this.oWebControl.JS_Video(url, this.currentMediaAccount, this.currentName, '', null, winNo)
      else
        this.oWebControl.JS_Video(url, this.currentMediaAccount, this.currentName, '')
    })
  }

  downloadPluginVideo(deviceCode, mediaAccount, gacode, rowId, begintime, endtime) {
    const startTime = timestampToTime(begintime)
    const endTime = timestampToTime(endtime)
    const data = {
      startTime,
      endTime,
      protocolType: 6,
      storageType: this.storageType,
      netType: this.islocal,
    }
    const url = `${southAddr}/devices/${deviceCode}/channels/${mediaAccount}/getVideoPlaybackUrl`
    post(url, data, {
      headers: {
        'X-ServerCode': 'getVideoPlaybackUrl',
        'X-PlugId': this.plugId,
      },
    }).then(({ data: result }) => {
      const url = result.data.streamUrl
      const streamControlId = result.data.streamControlId
      this.oWebControl.JS_PlaybackDownloadUrl(url, gacode, streamControlId, rowId)
    })
  }

  fetchPtzAuth(deviceCode, mediaAccount, controlType) {
    return new Promise((resolve, reject) => {
      const data = {
        duration: 60 * 1000,
      }
      const url = `${southAddr}/monitor/devices/${deviceCode}/channels/${mediaAccount}/ptz/${controlType}/doLockOrReleasePtz`
      post(url, data, {
        headers: {
          'X-ServerCode': 'doLockOrReleasePtz',
        },
      }).then(({ data: result }) => {})
    })
  }

  ptzCommand(operType, operContent, step) {
    return new Promise((resolve, reject) => {
      if (!this.currentWinCameraid) {
        reject('未获取到当前设备信息')
      } else {
        const deviceCode = this.currentDeviceCode
        const mediaAccount = this.currentMediaAccount
        const data = {
          operType,
          operContent,
          step: step || 1,
        }
        const url = `${southAddr}/plat/devices/${deviceCode}/channels/${mediaAccount}/ptz/doPtzCmds`
        post(url, data, {
          headers: {
            'X-ServerCode': 'doPtzCmds',
          },
        }).then(({ data: result }) => {
          resolve()
        })
      }
    })
  }

  doCameraFocusOrZoom(operType, operContent, step) {
    const data = {
      operType,
      operContent,
      step,
    }
    const deviceCode = this.currentDeviceCode
    const mediaAccount = this.currentMediaAccount
    const url = `${southAddr}/plat/devices/${deviceCode}/channels/${mediaAccount}/camera/doCameraFocusOrZoom`
    post(url, data, {
      headers: {
        'X-ServerCode': 'doCameraFocusOrZoom',
      },
    }).then(({ data: result }) => {})
  }

  pullAgain(gacode, winNo) {
    const data = {
      streamType: currentStreamType,
      protocolType: 6,
      netType: this.islocal,
    }
    setTimeout(() => {
      const url = `${southAddr}/devices/${this.currentDeviceCode}/channels/${this.currentMediaAccount}/getVideoRealtimeUrl`
      post(url, data, {
        headers: {
          'X-ServerCode': 'getVideoRealtimeUrl',
          'X-PlugId': this.plugId,
        },
      }).then(({ data: result }) => {
        const url = result.data.streamUrl
        this.oWebControl.JS_VideoAgain(url, this.currentMediaAccount, this.currentName, winNo)
      })
    }, 10000)
  }

  pullAgainSwich(gacode, winNo, streamType) {
    const data = {
      streamType,
      protocolType: 6,
      netType: this.islocal,
    }
    setTimeout(() => {
      const url = `${southAddr}/devices/${this.currentDeviceCode}/channels/${this.currentMediaAccount}/getVideoRealtimeUrl`
      post(url, data, {
        headers: {
          'X-ServerCode': 'getVideoRealtimeUrl',
          'X-PlugId': this.plugId,
        },
      }).then(({ data: result }) => {
        const url = result.data.streamUrl
        this.oWebControl.JS_VideoAgain(url, this.currentMediaAccount, this.currentName, winNo)
      })
    }, 10000)
  }

  playbackVideo(deviceCode, mediaAccount, name, begintime, winNo) {
    const startTime = timestampToTime(begintime)
    const endTime = `${startTime.split(' ')[0]} 23:59:59`
    const data = {
      startTime,
      endTime,
      protocolType: 6,
      storageType: this.storageType,
      netType: this.islocal,
    }
    const url = `${southAddr}/devices/${deviceCode}/channels/${mediaAccount}/getVideoPlaybackUrl`
    post(url, data, {
      headers: {
        'X-ServerCode': 'getVideoRealtimeUrl',
        'X-PlugId': this.plugId,
      },
    }).then(({ data: result }) => {
      const url = result.data.streamUrl
      const streamControlId = result.data.streamControlId
      this.oWebControl.JS_PlaybackUrl(url, deviceCode, name, winNo, streamControlId)
    })
  }

  handlePlayBack(channelInfo, timeObj, storage, winNo) {
    this.storageType = storage
    const data = {
      pageSize: 1000,
      currentPage: 1,
      storageType: this.storageType,
      recordType: 0,
      startTime: timeObj.start,
      endTime: timeObj.end,
    }
    const url = `${southAddr}/devices/${channelInfo.deviceCode}/channels/${channelInfo.mediaAccount}/queryVideoList`
    post(url, data, {
      headers: {
        'X-ServerCode': 'queryVideoList',
        'X-PlugId': this.plugId,
      },
    }).then(({ data: result }) => {
      const videos = result.data.videos
      let timeAxisArr = []
      if (videos && videos.length) {
        timeAxisArr = videos.map((item) => {
          return {
            nBeginTime: Number.parseInt(new Date(item.startTime).getTime() / 1000),
            nEndTime: Number.parseInt(new Date(item.endTime).getTime() / 1000),
            nFileSize: item.fileSize,
          }
        })
      } else {
        timeAxisArr = []
      }
      this.vRecordInfo[winNo] = {
        strGaCode: channelInfo.deviceCode,
        strName: channelInfo.name,
        vRecordTime: timeAxisArr,
      }
      const nQueryBeginTime = Number.parseInt(new Date(timeObj.start).getTime() / 1000)
      const nQueryEndTime = Number.parseInt(new Date(timeObj.end).getTime() / 1000) - 1
      this.oWebControl.JS_PlaybackThumb(nQueryBeginTime, nQueryEndTime, this.vRecordInfo)
    })
  }

  setCurrentDevice(deviceCode = {}, mediaAccount, name) {
    if (!deviceCode) return
    if (typeof deviceCode === 'string') {
      this.currentDeviceCode = deviceCode || this.currentDeviceCode
      this.currentMediaAccount = mediaAccount || this.currentMediaAccount
      this.currentName = name || this.currentName
    } else {
      const device = deviceCode
      this.currentDeviceCode = device.deviceCode || this.currentDeviceCode
      this.currentMediaAccount = device.mediaAccount || this.currentMediaAccount
      this.currentName = device.name || this.currentName
    }
  }
}

function timestampToTime(timestamp) {
  const date = new Date(timestamp * 1000)
  const Y = `${date.getFullYear()}-`
  const M = `${date.getMonth() + 1 < 10 ? `0${date.getMonth() + 1}` : date.getMonth() + 1}-`
  const D = `${date.getDate() < 10 ? `0${date.getDate()}` : date.getDate()} `
  const h = `${date.getHours() < 10 ? `0${date.getHours()}` : date.getHours()}:`
  const m = `${date.getMinutes() < 10 ? `0${date.getMinutes()}` : date.getMinutes()}:`
  const s = date.getSeconds() < 10 ? `0${date.getSeconds()}` : date.getSeconds()
  return Y + M + D + h + m + s
}

export function createArgesonPlayer(container, callbackFunc, reloadCount) {
  const argPlayer = new ArgesonPlayer()
  return argPlayer.initPlugin(container, callbackFunc, reloadCount)
}

const PlayerMap = new Map()

export const hideAndShowPlugin = function (type) {
  PlayerMap.forEach((player) => {
    player.hideAndShowPlugin(type)
  })
}

export const closeAllPlayers = function () {
  if (PlayerMap.size === 0) return
  PlayerMap.forEach((player) => {
    player?.destroy()
    Promise.resolve(() => {
      player.oWebControl = null
    })
  })
  PlayerMap.clear()
}

export const getEmptyPlayer = function () {
  const noop = () => {}
  return {
    initPlugin: noop,
    setPluginPosition: noop,
    playVideo: noop,
    checkClose: noop,
    downloadPluginVideo: noop,
    fetchPtzAuth: noop,
    ptzCommand: noop,
    doCameraFocusOrZoom: noop,
    pullAgain: noop,
    pullAgainSwich: noop,
    playbackVideo: noop,
    setSplitNum: noop,
    changeMatrixControl: noop,
    hideAndShowPlugin: noop,
    getPluginVersion: noop,
    closeVideoByWinNo: noop,
    changePluginMode: noop,
    pullVideoAgain: noop,
    turnToPreset: noop,
    handlePlayBack: noop,
    setCurrentDevice: noop,
    destroy: noop,
  }
}

